    public static void main(String[] args) {
        Coordinate c1 = new Coordinate(15, 30);
        Coordinate c2 = new Coordinate(15, 30);

        System.out.println("c1.hashCode(): " + c1.hashCode());
        System.out.println("c2.hashCode(): " + c2.hashCode());
        System.out.println("Hashes match:  " + (c1.hashCode() == c2.hashCode()));
    }
}

