import java.util.HashMap;
import java.util.Map;

// Intentionally poor hash code: forces all objects into the same bucket
class CollisionProneKey {
    private String keyName;
    public CollisionProneKey(String name) { this.keyName = name; }

    @Override
    public int hashCode() {
        return 42; // Constant hash! Every instance collides into bucket 42!
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        return keyName.equals(((CollisionProneKey) obj).keyName);
    }
}

public class CollisionDemo {
    public static void main(String[] args) {
        Map<CollisionProneKey, String> map = new HashMap<>();
        CollisionProneKey k1 = new CollisionProneKey("Alpha");
        CollisionProneKey k2 = new CollisionProneKey("Beta");

        map.put(k1, "First Value");
        map.put(k2, "Second Value");

        // Both live in the same bucket, but equals() differentiates them!
        System.out.println("Retrieved k1: " + map.get(k1));
        System.out.println("Retrieved k2: " + map.get(k2));
        System.out.println("Map size: " + map.size());
    }
}

