class GeoBoundingBox {
    private int minLat, maxLat, minLon, maxLon;

    public GeoBoundingBox(int minLat, int maxLat, int minLon, int maxLon) {
        this.minLat = minLat;
        this.maxLat = maxLat;
        this.minLon = minLon;
        this.maxLon = maxLon;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        GeoBoundingBox other = (GeoBoundingBox) obj;
        return minLat == other.minLat && maxLat == other.maxLat &&
               minLon == other.minLon && maxLon == other.maxLon;
    }

    @Override
    public int hashCode() {
        int result = 17;
        result = 31 * result + minLat;
        result = 31 * result + maxLat;
        result = 31 * result + minLon;
        result = 31 * result + maxLon;
        return result;
    }
}

public class BoundingBoxApp {
    public static void main(String[] args) {
        GeoBoundingBox b1 = new GeoBoundingBox(10, 20, 30, 40);
        GeoBoundingBox b2 = new GeoBoundingBox(10, 20, 30, 40);

        System.out.println("Equal: " + b1.equals(b2));
        System.out.println("Hashes match: " + (b1.hashCode() == b2.hashCode()));
    }
}

import java.util.Objects;

class CryptoToken {
    private final String rawHex;
    private int cachedHash = 0;

    public CryptoToken(String rawHex) {
        this.rawHex = rawHex;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        CryptoToken other = (CryptoToken) obj;
        return Objects.equals(rawHex, other.rawHex);
    }

    @Override
    public int hashCode() {
        if (cachedHash == 0) {
            cachedHash = rawHex.hashCode();
        }
        return cachedHash;
    }

    public boolean isHashCached() {
        return cachedHash != 0;
    }
}

public class TokenApp {
    public static void main(String[] args) {
        CryptoToken token = new CryptoToken("9f8a3b2c");
        System.out.println("Hash cached before call: " + token.isHashCached());
        token.hashCode();
        System.out.println("Hash cached after call: " + token.isHashCached());
    }
}

