class SimpleBucketTable {
    private int bucketCount;
    private int[] bucketSizes;

    public SimpleBucketTable(int bucketCount) {
        this.bucketCount = bucketCount;
        this.bucketSizes = new int[bucketCount];
    }

    public void insert(Object item) {
        int idx = Math.abs(item.hashCode()) % bucketCount;
        bucketSizes[idx]++;
    }

    public void printDistribution() {
        System.out.println("=== Bucket Histogram ===");
        for (int i = 0; i < bucketCount; i++) {
            System.out.println("Bucket " + i + ": " + bucketSizes[i] + " items");
        }
    }
}

public class HistogramApp {
    public static void main(String[] args) {
        SimpleBucketTable table = new SimpleBucketTable(4);
        String[] fruits = {"Apple", "Banana", "Cherry", "Date", "Elderberry", "Fig", "Grape", "Honeydew"};
        for (String f : fruits) {
            table.insert(f);
        }
        table.printDistribution();
    }
}
